{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "While early PA participation is known to be positively associated with adulthood PA, mental health, and cardiovascular health, the specific activity types that most optimally benefit health outcomes remain unclear. Previous systematic reviews have highlighted the influence of activity structure and type on psychosocial outcomes in children [22] and cardiovascular health in adults [23]. Another review identified a largely positive relationship between overall childhood sport participation and adulthood PA [24]. However, the longitudinal associations between participation in specific LTPA types during childhood and adolescence and adult health and PA behaviours remains unknown.",
      "reason": "The text describes the current state of knowledge (associations between early PA and health) and identifies the specific uncertainty (longitudinal associations between specific LTPA types in youth and adult outcomes)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Therefore, this systematic review aims to collate previous findings on the associations between participation in specific types of LTPA in childhood and adolescence, and PA behaviours and mental and cardiovascular health-related outcomes in adulthood.",
      "reason": "The text explains the need for the review by stating the aim to address the identified knowledge gap regarding specific LTPA types and their long-term health associations."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Previous systematic reviews have highlighted the influence of activity structure and type on psychosocial outcomes in children [22] and cardiovascular health in adults [23]. Another review identified a largely positive relationship between overall childhood sport participation and adulthood PA [24]. However, the longitudinal associations between participation in specific LTPA types during childhood and adolescence and adult health and PA behaviours remains unknown.",
      "reason": "The authors acknowledge previous reviews and explain that the current review is needed because the longitudinal associations between specific LTPA types and adult outcomes remain unknown."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of intervention effects; it is a review of longitudinal associations between physical activity types and health outcomes."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of complex interventions or delivery contexts."
    }
  ],
  "confidence": 100
}

