{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Studies were eligible for inclusion if they met the following criteria: - (i) Full-text original peer-reviewed journal article published in English; - (ii) observational study design on humans with at least two timepoints of data collection; - (iii) cohort from the general population, - (iv) measurement of at least one specific type of LTPA (e.g., tennis, walking, strength-training), or grouping of specific types of LTPA with similar attributes (e.g., team sports, ball sports), in childhood or adolescence (aged 5-18 years); - (v) quantitative assessment of at least one mental health outcome (e.g., depression or anxiety symptoms/ diagnosis), cardiovascular health outcome (e.g., BMI, waist circumference, cholesterol, cardiovascular events/disease), or PA outcome in adulthood (aged 18 + years). Studies were excluded based on the presence of the following criteria: - (i) Focussed on targeted populations (i.e., populations with known disease or special interest groups); - (ii) considered setting or mode of activity instead of type (e.g., non-organised vs. organised sport, school vs. - non-school setting).",
      "reason": "The manuscript explicitly specifies inclusion and exclusion criteria regarding study design (observational, longitudinal), population (general, age range), exposure (specific types of LTPA), and outcomes (mental health, cardiovascular, PA)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Studies were eligible for inclusion if they met the following criteria: - (i) Full-text original peer-reviewed journal article published in English; ... No date restrictions were imposed on the search.",
      "reason": "The manuscript specifies report characteristics including publication status (peer-reviewed), language (English), and dissemination date (no restrictions)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not distinguish between studies excluded because outcomes were not measured versus studies excluded because outcome results were not reported. The PRISMA flowchart (Fig. 1) simply lists 'Wrong outcomes' as an exclusion category."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript states that a narrative synthesis was performed but does not specify how studies were grouped for these syntheses (e.g., by outcome type or exposure type)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "While the manuscript lists restrictions (e.g., English language, peer-reviewed), it does not provide a rationale for these specific restrictions."
    }
  ],
  "confidence": 100
}

